INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(95744, 'ruRU', '', 'Приветствую, командир! Кадгар рассказывал мне о твоих многочисленных великих деяниях...', 24330),
(95745, 'ruRU', '', 'Преклони колено, защитник. Это редкая и особая привилегия — быть благословлённым наару.', 24330),
(95752, 'ruRU', '', 'Ты что-нибудь слышал? Наару говорил с тобой?', 24330),
(95753, 'ruRU', '', 'Командир, что бы ты ни решил делать дальше, знай — у тебя полная поддержка народа дренеев.', 24330),
(95754, 'ruRU', '', 'Мы с тобой!', 24330),
(95766, 'ruRU', '', 'Наездники на грифонах, прикройте их!', 24330),
(95767, 'ruRU', '', 'Герой! <кашляет> Убери эти химические сигнальные ракеты подальше от боеприпасов!', 24330),
(95790, 'ruRU', '', 'Ничего.$b$bНичего, что тебя касается.$b$bЯ держу всё под контролем.', 24330),
(95796, 'ruRU', '', 'Да, твоё кольцо. ТО САМОЕ кольцо! То, которое Кадгар готовил для тебя с самого нашего прибытия на Дренор.$b$bДавай его сюда. Я просто хочу... одолжить его.', 24330),
(95803, 'ruRU', '', 'Отец, прошу тебя! Незнакомец, прости нас. В эти дни мы все немного настороженно относимся к чужакам.', 24330),
(95804, 'ruRU', '', 'Шипы — это средство защиты для зелёных растущих созданий: хрупкой флоры, что иначе была бы беззащитна.$B$BНе кляни шипы. Радуйся цветению, которое они делают возможным.', 24330),
(95805, 'ruRU', '', 'Когда наши сердца слабеют, мы перестаём уважать мир вокруг нас.$B$BПрирода держит зеркало перед нашими душами.', 24330),
(95853, 'ruRU', '', 'Как и Лунная поляна, эта деревня и её обитатели под моей защитой. Жаль, что я не могу укрыть больше дикой природы и её хранителей.$B$BЕсли бы я только был достаточно силён, чтобы защитить вас всех.', 24330),
(95854, 'ruRU', '', 'Я никогда не видел этих фей такими взволнованными.', 24330),
(95858, 'ruRU', '', 'Здесь ты можешь отдохнуть, не боясь кошмаров.', 24330),
(95859, 'ruRU', '', 'Шипочешуйки всегда были лёгкой докукой. Но в последнее время их поведение изменилось от ребячливого до враждебного и разрушительного.$B$BЯ не знаю, что вызвало эту перемену, но нужно что-то предпринять, чтобы защитить этих фей-драконов.', 24330),
(95863, 'ruRU', '', 'Командир, подкрепления прибывают ежедневно. Используй этот портал, чтобы путешествовать между этим местом и нашим оплотом в Ашране.', 24330),
(95869, 'ruRU', '', 'Теперь, мои воины! До Чертогов Доблести считанные мгновения!', 24330),
(95874, 'ruRU', '', 'Давай, беги, я не стану прятаться под палаткой! Если следующий выстрел предназначен мне — так тому и быть.', 24330),
(95875, 'ruRU', '', 'Я знаю твою цель, Королева банши! Тебе стоит отступить, пока не навлекла на себя мой гнев!', 24330),
(95878, 'ruRU', '', 'Откажешься — и я заберу твои дары силой!', 24330),
(95880, 'ruRU', '', 'Глупая девчонка! Тебе не постичь силы, с которыми ты вмешиваешься.', 24330),
(95881, 'ruRU', '', 'Ты падёшь из-за собственной гордыни. Как и та, что тебя создала.', 24330),
(95889, 'ruRU', '', 'Мы успеем захватить Эгиду вовремя — нельзя упустить эту возможность устранить Сильвану!', 24330),
(95891, 'ruRU', '', 'Сильвана заплатит за свои преступления...', 24330),
(95895, 'ruRU', '', 'Для меня честь сражаться рядом с тобой, $n. С того самого момента, когда я впервые встретил тебя в том ужасном туннеле за Тёмным порталом, твоё присутствие всегда меня вдохновляло.$b$bК''ара тоже видит твою внутреннюю силу. Готов поговорить с наару?', 24330),
(95897, 'ruRU', '', 'Тебе не положено быть здесь наверху, $n.', 24330),
(95898, 'ruRU', '', 'Остальные говорили о |5$r $c, который умеет шить. Полагаю, это ты и есть.$b$bЕсли Титалло считает, что ты готов, я могу показать тебе Станок Королевской Милости.', 24330),
(95899, 'ruRU', '', 'Приветствую, $n.', 24330),
(95900, 'ruRU', '', 'Чт-что это за сила?! Этого... не может быть...', 24330),
(95902, 'ruRU', '', 'Сам станок, честно говоря, ничего особенного не представляет.$b$bБезусловно, это красивая вещь. Довольно старая, но по сути — просто ольховое дерево да несколько гвоздей. Мы делаем всё возможное, чтобы его поддерживать.$b$bНо нет, сам станок не имеет значения для наших методов.', 24330),
(95903, 'ruRU', '', 'Как внимательно с твоей стороны. Да, наш орден заключил сделку с высшей силой, чтобы обрести больше мастерства в своём ремесле.$b$bЯ готов показать тебе наш секрет. Узри силу Лей-ткачей!', 24330),
(95906, 'ruRU', '', 'Я совсем на него не похожа! Узри!', 24330),
(95909, 'ruRU', '', 'Дар от твоей сестры, Хелии. А теперь... преклони колени!', 24330),
(95919, 'ruRU', '', 'Мы заключили соглашение с Гул''даном. Мы снабжаем его и его силы припасами, а взамен он предоставил нам нескольких своих наиболее способных дознавателей.', 24330),
(95920, 'ruRU', '', 'Конечно, я бы предпочёл, чтобы лей-ткачи обходились без чьей-либо помощи, но качество этой пропитанной демонической силой ткани намного превосходит всё, что мы могли бы сделать сами.', 24330),
(95921, 'ruRU', '', 'Мы портные, $n, и ты тоже. Никакая цена не слишком высока, если речь идёт о лучшей мантии. Я прав?', 24330),
(95925, 'ruRU', '', 'По миру странствует множество других лей-ткачей. Я могу показать тебе, где они.', 24330),
(95927, 'ruRU', '', 'Что тебе нужно?', 24330),
(95928, 'ruRU', '', 'Будь осторожен там!', 24330);
